#include <bits/stdc++.h>

using namespace std;

typedef long long ll;

const int MAXN = 5007;
const ll INF = 1e9;
const ll MOD = 1e9 + 7;

struct Edge {
    int from, to;
    ll cap, cost, flow;
    Edge(int from, int to, ll cap, ll cost) : from(from), to(to), cap(cap), cost(cost), flow(0) {}
};

vector<Edge> edges;
vector<int> graph[MAXN];
ll dist[MAXN], pot[MAXN];
int parent[MAXN];

void add_edge(int u, int v, ll cap, ll cost) {
    graph[u].push_back(edges.size());
    edges.push_back({u, v, cap, cost});
    graph[v].push_back(edges.size());
    edges.push_back({v, u, 0, -cost});
}

void bellman_ford(int s, int n) {
    fill(pot, pot + MAXN, INF);
    pot[s] = 0;
    for (int i = 0; i < n; i++) {
        for (size_t j = 0; j < edges.size(); j++) {
            Edge &e = edges[j];
            if (e.cap == e.flow || pot[e.from] == INF) continue;
            pot[e.to] = min(pot[e.to], pot[e.from] + e.cost);
        }
    }
}

void dijkstra(int s) {
    fill(dist, dist + MAXN, INF);
    dist[s] = 0;
    set<pair<ll, int>> pq;
    pq.insert({0, s});
    while (!pq.empty()) {
        int v = pq.begin()->second;
        pq.erase(pq.begin());
        for (size_t i = 0; i < graph[v].size(); i++) {
            int id = graph[v][i];
            Edge &e = edges[id];
            if (e.cap == e.flow) continue;
            int to = e.to;
            ll w = e.cost + pot[v] - pot[to];
            if (dist[v] + w < dist[to]) {
                pq.erase({dist[to], to});
                dist[to] = dist[v] + w;
                parent[to] = id;
                pq.insert({dist[to], to});
            }
        }
    }
}

pair<ll, ll> mincost_maxflow(int s, int t) {
    bellman_ford(s, 50);
    dijkstra(s);
    ll flow = 0, cost = 0;
    while (true) {
        if (dist[t] == INF) break;
        ll pushed = INF, sum = 0;
        for (int v = t; v != s; v = edges[parent[v]].from) {
            pushed = min(pushed, edges[parent[v]].cap - edges[parent[v]].flow);
            sum += edges[parent[v]].cost;
        }
        flow += pushed;
        cost += pushed * sum;
        for (int v = t; v != s; v = edges[parent[v]].from) {
            int id = parent[v];
            edges[id].flow += pushed;
            edges[id ^ 1].flow -= pushed;
        }
        dijkstra(s);
        copy(dist, dist + MAXN, pot);
    }
    return {cost, flow};
}

void solve() {
    int n, m, k, c, d;
    cin >> n >> m >> k >> c >> d;
    vector<int> cnt(n, 0);
    for (int i = 0; i < k; i++) {
        int x;
        cin >> x;
        cnt[--x]++;
    }
    for (int i = 0; i < n; i++) add_edge(5000, i, cnt[i], 0);
    for (int i = 0; i < m; i++) {
        int u, v;
        cin >> u >> v;
        u--, v--;
        for (int j = 0; j < 99; j++) {
            ll cost = d;
            for (int t = 0; t < 50; t++) {
                add_edge(u + j * 50, v + (j + 1) * 50, 1, cost);
                add_edge(v + j * 50, u + (j + 1) * 50, 1, cost);
                cost += 2 * d;
            }
        }
    }
    for (int i = 0; i <= 99; i++) add_edge(0 + i * 50, 5001, INF, c * i);
    for (int i = 0; i < n; i++)
        for (int j = 0; j < 99; j++)
            add_edge(i + j * 50, i + (j + 1) * 50, INF, 0);
    auto answer = mincost_maxflow(5000, 5001);
    assert(answer.second == k);
    cout << answer.first;
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);
    cout.tie(nullptr);
    cout << fixed << setprecision(20);
    solve();
    return 0;
}
